// CWE-190 / CWE-681: an arithmetic helper on integers never returns a wrong or unsafe result silently.
import * as fc from 'fast-check';
import { show } from './cwe.ts';
import { securityLaw } from './law.ts';
import type { SecurityLaw } from './law.ts';

/** Two operands for a law parameter: `law add(p: IntPair) => safeAdd.holds(p)`. Generated by `intPairs`. */
export interface IntPair {
  a: number;
  b: number;
}

const max = Number.MAX_SAFE_INTEGER;

const edges = [
  0,
  1,
  -1,
  2,
  -2,
  255,
  256,
  65535,
  65536,
  2 ** 31 - 1,
  2 ** 31,
  -(2 ** 31),
  2 ** 32 - 1,
  2 ** 32,
  2 ** 26,
  2 ** 26 + 1,
  2 ** 27,
  2 ** 52,
  2 ** 53 - 2,
  max - 1,
  max,
  -max,
  -max + 1,
];

/** Operands at the edges of 8, 16, 32 and 53 bits, plus uniform safe integers and numbers whose product or sum crosses 2^53. */
export function intPairs(options: { unsafeInputs?: boolean } = {}): fc.Arbitrary<IntPair> {
  const near = fc.constantFrom(...edges);
  const wide = fc.integer({ min: -max, max });
  const bits = fc
    .tuple(fc.integer({ min: 1, max: 53 }), fc.boolean())
    .chain(([n, negative]) => fc.integer({ min: 0, max: 2 ** n - 1 }).map((v) => (negative ? -v : v)));
  const operand = fc.oneof(
    { weight: 4, arbitrary: near },
    { weight: 2, arbitrary: wide },
    { weight: 4, arbitrary: bits },
  );
  const safe = fc.record({ a: operand, b: operand });
  if (options.unsafeInputs !== true) return safe;
  const unsafe = fc.constantFrom(max + 1, max + 2, -max - 2, 2 ** 53 + 2, 2 ** 60, 1.5, -0.5, NaN, Infinity, -Infinity);
  return fc.oneof(
    { weight: 6, arbitrary: safe },
    { weight: 1, arbitrary: fc.record({ a: unsafe, b: operand }) },
    { weight: 1, arbitrary: fc.record({ a: operand, b: unsafe }) },
  );
}

export interface SafeArithmeticOptions {
  /** The exact operation: `add`, `sub`, `mul`, or your own on bigints (a pow, a ceil-div, a size computation). */
  exact: 'add' | 'sub' | 'mul' | ((a: bigint, b: bigint) => bigint);
  /**
   * What an out-of-range result may be. `refuse` (the default): the helper throws or returns NaN, null or undefined.
   * `saturate`: it may also return the safe-integer limit of the right sign.
   */
  overflow?: 'refuse' | 'saturate';
  /**
   * Also feed operands that are not safe integers (above 2^53, fractions, NaN, Infinity); the helper must refuse them
   * (CWE-681: a conversion that quietly loses precision). Default false.
   */
  unsafeInputs?: boolean;
}

const operations = {
  add: (a: bigint, b: bigint) => a + b,
  sub: (a: bigint, b: bigint) => a - b,
  mul: (a: bigint, b: bigint) => a * b,
};

const bigMax = BigInt(max);

/**
 * CWE-190 and CWE-681. For safe-integer operands `op(a, b)` must return the exact result when it is a safe integer,
 * and otherwise throw (or return NaN, null or undefined; or saturate, if allowed). A result that is rounded, wrapped
 * or past 2^53 - 1 fails, as does an unrefused operand that is not a safe integer when `unsafeInputs` is set.
 */
export function safeArithmetic(
  op: (a: number, b: number) => unknown,
  options: SafeArithmeticOptions,
): SecurityLaw<IntPair> {
  const exactOf = typeof options.exact === 'function' ? options.exact : operations[options.exact];
  const refused = (r: unknown): boolean => r === undefined || r === null || (typeof r === 'number' && Number.isNaN(r));
  return securityLaw<IntPair>({
    id: 'safe-arithmetic',
    cwe: ['CWE-190', 'CWE-681'],
    title: 'an integer helper returns the exact result or refuses; it never overflows or rounds silently',
    input: intPairs({ unsafeInputs: options.unsafeInputs }),
    corpus: edges.flatMap((a) => [
      { a, b: max },
      { a, b: -max },
      { a, b: 2 ** 27 },
    ]),
    verdict: ({ a, b }) => {
      const call = `op(${show(a)}, ${show(b)})`;
      let result: unknown;
      try {
        result = op(a, b);
      } catch {
        return undefined;
      }
      if (!Number.isSafeInteger(a) || !Number.isSafeInteger(b))
        return options.unsafeInputs === true && !refused(result)
          ? { cwe: ['CWE-681'], detail: `${call} returned ${show(result)} for an operand that is not a safe integer` }
          : undefined;
      if (refused(result)) return undefined;
      const exact = exactOf(BigInt(a), BigInt(b));
      if (typeof result === 'bigint')
        return result === exact
          ? undefined
          : { cwe: ['CWE-190'], detail: `${call} returned ${show(String(result))}, not ${show(String(exact))}` };
      if (typeof result !== 'number')
        return { cwe: ['CWE-681'], detail: `${call} returned ${show(result)}, not a number` };
      const inRange = exact <= bigMax && exact >= -bigMax;
      if (!inRange) {
        if (options.overflow === 'saturate' && result === (exact > 0n ? max : -max)) return undefined;
        return {
          cwe: ['CWE-190'],
          detail: `${call} returned ${show(result)}, but the exact result ${exact} is not a safe integer`,
        };
      }
      if (!Number.isSafeInteger(result) || BigInt(result) !== exact)
        return { cwe: ['CWE-190'], detail: `${call} returned ${show(result)}, but the exact result is ${exact}` };
      return undefined;
    },
  });
}
